//! Vendored Bazel / intellij-aspect protobuf code, generated by prost-build in build.rs.
//!
//! Generated files are raw items for their proto package, so each file must be
//! wrapped in a module matching the package path. Aspect protos (`TargetIdeInfo`
//! & co) have no proto package, so their items sit at the `gen` root.

#![allow(clippy::large_enum_variant)]

#[allow(clippy::all, rustdoc::all)] // generated by prost: doc lints fire on vendored docs
pub mod gen {
    // packageless aspect protos (sdk/proto/ide_info.proto, sdk/proto/common.proto)
    include!(concat!(env!("OUT_DIR"), "/_.rs"));

    pub mod blaze {
        // action_cache.proto (package blaze)
        include!(concat!(env!("OUT_DIR"), "/blaze.rs"));

        pub mod invocation_policy {
            include!(concat!(env!("OUT_DIR"), "/blaze.invocation_policy.rs"));
        }
        pub mod strategy_policy {
            include!(concat!(env!("OUT_DIR"), "/blaze.strategy_policy.rs"));
        }
    }

    pub mod blaze_query {
        include!(concat!(env!("OUT_DIR"), "/blaze_query.rs"));
    }

    pub mod build_event_stream {
        include!(concat!(env!("OUT_DIR"), "/build_event_stream.rs"));
    }

    pub mod command_line {
        include!(concat!(env!("OUT_DIR"), "/command_line.rs"));
    }

    pub mod options {
        include!(concat!(env!("OUT_DIR"), "/options.rs"));
    }

    pub mod failure_details {
        include!(concat!(env!("OUT_DIR"), "/failure_details.rs"));
    }

    pub mod stardoc_output {
        include!(concat!(env!("OUT_DIR"), "/stardoc_output.rs"));
    }

    pub mod devtools {
        pub mod build {
            pub mod lib {
                pub mod packages {
                    pub mod metrics {
                        include!(concat!(env!("OUT_DIR"), "/devtools.build.lib.packages.metrics.rs"));
                    }
                }
            }
        }
    }
}

pub use gen::{blaze_query, build_event_stream};

/// The vendored intellij-aspect bzl sources (contents of the deployed
/// `archive_ide.zip`: `common/`, `intellij/`, `modules/`), embedded at build
/// time — used by the deployer in `baztet-core`.
pub fn embedded_aspect_files() -> &'static [(&'static str, &'static [u8])] {
    include!(concat!(env!("OUT_DIR"), "/aspect_files.rs"))
}

/// `prost-reflect` descriptor pool for all vendored protos. Used to parse the
/// text-format `*.intellij-info.txt` aspect outputs into dynamic messages.
pub fn descriptor_pool() -> prost_reflect::DescriptorPool {
    static POOL: std::sync::OnceLock<prost_reflect::DescriptorPool> = std::sync::OnceLock::new();
    POOL.get_or_init(|| {
        let bytes = include_bytes!(concat!(env!("OUT_DIR"), "/descriptor.bin"));
        prost_reflect::DescriptorPool::decode(&bytes[..]).expect("valid FileDescriptorSet")
    })
    .clone()
}

/// Descriptor for the aspect's `TargetIdeInfo` message.
pub fn target_ide_info_descriptor() -> prost_reflect::MessageDescriptor {
    descriptor_pool()
        .get_message_by_name("TargetIdeInfo")
        .expect("TargetIdeInfo in descriptors")
}

#[cfg(test)]
mod tests {
    use crate::gen;

    #[test]
    fn text_format_parse() {
        let desc = crate::target_ide_info_descriptor();
        let msg = prost_reflect::DynamicMessage::parse_text_format(
            desc,
            r#"key { label: "//x:lib" }"#,
        )
        .expect("textproto must parse");
        let label = msg
            .get_field_by_name("key")
            .unwrap()
            .as_ref()
            .as_message()
            .and_then(|m| m.get_field_by_name("label"))
            .map(|v| v.as_str().map(str::to_owned));
        assert_eq!(label, Some(Some("//x:lib".to_string())));
    }

    #[test]
    fn unknown_text_fields_fail() {
        // prost-reflect rejects unknown fields (unlike the Kotlin SDK parser);
        // callers must treat a failed parse as an unparseable target and skip it.
        let desc = crate::target_ide_info_descriptor();
        let msg =
            prost_reflect::DynamicMessage::parse_text_format(desc, "not_a_known_field: 1");
        assert!(msg.is_err());
    }

    #[test]
    fn query_bep_aspect_messages_exist() {
        use prost::Message;
        // proto2 types; just check they round-trip an empty message.
        let t = gen::blaze_query::Target::default();
        let back = gen::blaze_query::Target::decode(t.encode_to_vec().as_ref()).unwrap();
        assert_eq!(back.encode_to_vec(), t.encode_to_vec());

        // proto2 default presence: a default Target encodes explicitly.
        assert!(!t.encode_to_vec().is_empty());

        let e = gen::build_event_stream::BuildEvent::default();
        assert!(gen::build_event_stream::BuildEvent::decode(e.encode_to_vec().as_ref()).is_ok());

        let i = gen::TargetIdeInfo::default();
        assert!(gen::TargetIdeInfo::decode(i.encode_to_vec().as_ref()).is_ok());

        let pool = crate::descriptor_pool();
        assert!(pool.get_message_by_name("build_event_stream.BuildEvent").is_some());
        assert!(pool.get_message_by_name("blaze_query.Target").is_some());
    }

    #[test]
    fn delimited_roundtrip() {
        use prost::Message;
        let t = gen::blaze_query::Target::default();
        let mut buf = Vec::new();
        t.encode_length_delimited(&mut buf).unwrap();
        let back = gen::blaze_query::Target::decode_length_delimited(&buf[..]).unwrap();
        assert_eq!(back.encode_to_vec(), t.encode_to_vec());
    }
}